439: /* ============ ICON RESOLUTION (Lucide name OR raw SVG) ============ */
440: const LUCIDE_NAMES = new Set();
441: (function buildLucideNames(){
442:   if(window.lucide && lucide.icons){
443:     Object.keys(lucide.icons).forEach(k=>{
444:       const kebab = k.replace(/([a-z0-9])([A-Z])/g,'$1-$2').replace(/([A-Z]+)([A-Z][a-z])/g,'$1-$2').toLowerCase();
445:       LUCIDE_NAMES.add(kebab);
446:     });
447:   }
448: })();
449: function resolveIconName(name){
450:   if(!name) return 'app-window';
451:   return LUCIDE_NAMES.has(name) ? name : 'app-window';
452: }
453: function normalizeSvg(svg){
454:   return svg.replace(/<svg([^>]*)>/i, (m, attrs)=>{
455:     let a = attrs.replace(/\s(width|height)="[^"]*"/gi,'');
456:     return `<svg${a} width="100%" height="100%">`;
457:   });
458: }
459: function iconMarkup(app){
460:   if(app.svg) return `<span style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;">${normalizeSvg(app.svg)}</span>`;
461:   return `<i data-lucide="${app.icon}"></i>`;
462: }
