664: /* ============ WINDOW MANAGEMENT ============ */
665: function openApp(key){
666:   if(openWindows[key] && openWindows[key].el){
667:     restoreWindow(key);
668:     focusWindow(key);
669:     return;
670:   }
671:   createWindow(key);
672: }
673: function toggleApp(key){
674:   if(openWindows[key] && openWindows[key].el){
675:     const w = openWindows[key];
676:     if(w.minimized || w.el.style.display==='none'){ restoreWindow(key); focusWindow(key); }
677:     else if(isFocused(key)){ minimizeWindow(key); }
678:     else { focusWindow(key); }
679:   } else {
680:     createWindow(key);
681:   }
682: }
683: function isFocused(key){
684:   return openWindows[key] && openWindows[key].el.classList.contains('focused');
685: }
