687: function createWindow(key){
688:   const app = APPS[key];
689:   const layer = document.getElementById('windows-layer');
690:   const id = 'win-'+key;
691:   const el = document.createElement('div');
692:   el.className='window';
693:   el.id = id;
694:   winCount++;
695:   const offset = (winCount%6)*26;
696:   const w = key==='calc'? 320 : 640, h = key==='calc'? 480: 440;
697:   el.style.width = w+'px';
698:   el.style.height = h+'px';
699:   el.style.left = (90+offset)+'px';
700:   el.style.top = (50+offset)+'px';
701:   el.style.zIndex = ++zTop;
702: 
703:   el.innerHTML = `
704:     <div class="win-titlebar">
705:       <span class="win-ico" style="display:inline-flex;width:16px;height:16px;">${iconMarkup(app)}</span>
706:       <div class="win-title">${app.name}</div>
707:       <div class="win-controls">
708:         <button class="win-btn min" title="Minimize"><i data-lucide="minus"></i></button>
709:         <button class="win-btn max" title="Maximize"><i data-lucide="square"></i></button>
710:         <button class="win-btn close" title="Close"><i data-lucide="x"></i></button>
711:       </div>
712:     </div>
713:     <div class="win-body"></div>
714:     <div class="resize-handle"></div>
715:   `;
716:   layer.appendChild(el);
717:   const body = el.querySelector('.win-body');
718:   app.render(body, key);
719: 
720:   openWindows[key] = {el, minimized:false, maximized:false, prevRect:null};
721: 
722:   el.addEventListener('mousedown', ()=>focusWindow(key));
723:   makeDraggable(el, el.querySelector('.win-titlebar'));
724:   makeResizable(el, el.querySelector('.resize-handle'));
725: 
726:   el.querySelector('.min').onclick = (e)=>{e.stopPropagation(); minimizeWindow(key);};
727:   el.querySelector('.max').onclick = (e)=>{e.stopPropagation(); toggleMaximize(key);};
728:   el.querySelector('.close').onclick = (e)=>{e.stopPropagation(); closeWindow(key);};
729:   el.querySelector('.win-titlebar').ondblclick = ()=>toggleMaximize(key);
730: 
731:   addTaskbarRunning(key);
732:   focusWindow(key);
733:   lucide.createIcons();
734: }
