736: function addTaskbarRunning(key){
737:   const app = APPS[key];
738:   const run = document.getElementById('running-apps');
739:   if(app.pinned){
740:     const pinBtn = pinnedLayer.querySelector(`[data-app="${key}"]`);
741:     pinBtn.classList.add('running','active');
742:     return;
743:   }
744:   let b = run.querySelector(`[data-app="${key}"]`);
745:   if(!b){
746:     b = document.createElement('button');
747:     b.className='taskbar-app running active';
748:     b.dataset.app = key;
749:     b.innerHTML = `<span style="display:inline-flex;width:17px;height:17px;">${iconMarkup(app)}</span><span>${app.name}</span>`;
750:     b.onclick = ()=>toggleApp(key);
751:     run.appendChild(b);
752:     lucide.createIcons();
753:   }
