1217:           <button id="pw-copy" style="background:var(--bg-3);border:1px solid var(--line-soft);border-radius:8px;width:34px;height:34px;display:flex;align-items:center;justify-content:center;color:var(--text-1);cursor:pointer;flex:0 0 auto;"><i data-lucide="copy" style="width:14px;height:14px;"></i></button>
1218:         </div>
1219:         <div class="set-row"><div class="lbl">Length: <span id="pw-len-val">16</span></div><input id="pw-len" type="range" min="6" max="48" value="16" style="width:160px;accent-color:var(--accent);"></div>
1220:         <div class="set-row"><div class="lbl">Uppercase (A–Z)</div><div class="toggle on" data-k="upper"><div class="knob"></div></div></div>
1221:         <div class="set-row"><div class="lbl">Lowercase (a–z)</div><div class="toggle on" data-k="lower"><div class="knob"></div></div></div>
1222:         <div class="set-row"><div class="lbl">Numbers (0–9)</div><div class="toggle on" data-k="numbers"><div class="knob"></div></div></div>
1223:         <div class="set-row"><div class="lbl">Symbols (!@#$…)</div><div class="toggle on" data-k="symbols"><div class="knob"></div></div></div>
1224:         <button id="pw-gen" style="width:100%;margin-top:8px;background:var(--accent);border:none;border-radius:9px;padding:11px;color:#08110F;font-weight:600;font-size:12.5px;cursor:pointer;font-family:var(--font-body);display:flex;align-items:center;justify-content:center;gap:7px;">
1225:           <i data-lucide="refresh-cw" style="width:14px;height:14px;"></i>Generate new password
1226:         </button>
1227:       </div>
1228:     </div>
1229:   `;
1230:   lucide.createIcons();
1231:   const opts = {upper:true, lower:true, numbers:true, symbols:true};
1232:   const lenInput = body.querySelector('#pw-len');
1233:   const lenVal = body.querySelector('#pw-len-val');
1234:   const output = body.querySelector('#pw-output');
1235:   const sets = {
1236:     upper:'ABCDEFGHIJKLMNOPQRSTUVWXYZ', lower:'abcdefghijklmnopqrstuvwxyz',
1237:     numbers:'0123456789', symbols:'!@#$%^&*()-_=+[]{}?'
1238:   };
1239:   function generate(){
1240:     let pool = '';
1241:     Object.keys(opts).forEach(k=>{ if(opts[k]) pool += sets[k]; });
1242:     if(!pool){ output.textContent = 'Select at least one character type'; return; }
1243:     const len = parseInt(lenInput.value);
1244:     const arr = new Uint32Array(len);
1245:     crypto.getRandomValues(arr);
1246:     let pass = '';
1247:     for(let i=0;i<len;i++) pass += pool[arr[i] % pool.length];
1248:     output.textContent = pass;
1249:   }
1250:   lenInput.addEventListener('input', ()=>{ lenVal.textContent = lenInput.value; generate(); });
1251:   body.querySelectorAll('.toggle[data-k]').forEach(t=>{
1252:     t.onclick = ()=>{ const k=t.dataset.k; opts[k]=!opts[k]; t.classList.toggle('on'); generate(); };
1253:   });
1254:   body.querySelector('#pw-gen').onclick = generate;
1255:   body.querySelector('#pw-copy').onclick = ()=>{
1256:     navigator.clipboard?.writeText(output.textContent).then(()=>showToast('check','Copied','Password copied to clipboard'));
1257:   };
1258:   generate();
1259: }
