1298: const UNIT_GROUPS = {
1299:   Length: { m:1, km:1000, cm:0.01, mm:0.001, mi:1609.344, yd:0.9144, ft:0.3048, in:0.0254 },
1300:   Weight: { kg:1, g:0.001, mg:0.000001, lb:0.453592, oz:0.0283495, ton:1000 },
1301:   Temperature: null, // special-cased
1302:   Data: { B:1, KB:1024, MB:1024**2, GB:1024**3, TB:1024**4 },
1303: };
1304: function renderUnits(body){
1305:   body.innerHTML = `
1306:     <div class="app-pane">
1307:       <div class="app-toolbar">
1308:         <div class="seg" id="un-group" style="flex:1;">
1309:           <button data-g="Length" class="active">Length</button>
1310:           <button data-g="Weight">Weight</button>
1311:           <button data-g="Temperature">Temp</button>
1312:           <button data-g="Data">Data</button>
1313:         </div>
1314:       </div>
1315:       <div class="content" style="max-width:420px;">
1316:         <div style="display:flex;gap:10px;align-items:center;margin-bottom:16px;">
1317:           <input id="un-val" type="number" value="1" style="flex:1;background:var(--bg-2);border:1px solid var(--line-soft);border-radius:8px;padding:9px 10px;color:var(--text-0);font-size:14px;outline:none;">
1318:           <select id="un-from" style="background:var(--bg-2);border:1px solid var(--line-soft);border-radius:8px;padding:9px 8px;color:var(--text-0);font-size:13px;outline:none;"></select>
1319:           <i data-lucide="arrow-right" style="width:15px;height:15px;stroke:var(--text-2);flex:0 0 auto;"></i>
1320:           <select id="un-to" style="background:var(--bg-2);border:1px solid var(--line-soft);border-radius:8px;padding:9px 8px;color:var(--text-0);font-size:13px;outline:none;"></select>
1321:         </div>
1322:         <div id="un-result" style="background:var(--bg-2);border:1px solid var(--line-soft);border-radius:12px;padding:20px;text-align:center;">
1323:           <div style="font-family:var(--font-display);font-size:30px;font-weight:600;color:var(--accent);" id="un-result-val">—</div>
1324:         </div>
1325:       </div>
1326:     </div>
1327:   `;
1328:   lucide.createIcons();
1329:   let group = 'Length';
1330:   const fromSel = body.querySelector('#un-from');
1331:   const toSel = body.querySelector('#un-to');
1332:   const valInput = body.querySelector('#un-val');
1333:   const resultVal = body.querySelector('#un-result-val');
1334: 
1335:   function populate(){
1336:     const units = group==='Temperature' ? ['C','F','K'] : Object.keys(UNIT_GROUPS[group]);
1337:     fromSel.innerHTML = units.map(u=>`<option value="${u}">${u}</option>`).join('');
1338:     toSel.innerHTML = units.map((u,i)=>`<option value="${u}" ${i===1?'selected':''}>${u}</option>`).join('');
1339:     compute();
1340:   }
1341:   function tempToC(v,u){ return u==='C'?v : u==='F'? (v-32)*5/9 : v-273.15; }
1342:   function cToTemp(c,u){ return u==='C'?c : u==='F'? c*9/5+32 : c+273.15; }
1343:   function compute(){
1344:     const v = parseFloat(valInput.value);
1345:     if(isNaN(v)){ resultVal.textContent='—'; return; }
1346:     let out;
1347:     if(group==='Temperature'){
1348:       out = cToTemp(tempToC(v, fromSel.value), toSel.value);
1349:     } else {
1350:       const table = UNIT_GROUPS[group];
1351:       out = v * table[fromSel.value] / table[toSel.value];
1352:     }
1353:     resultVal.textContent = (Math.round(out*10000)/10000).toLocaleString() + ' ' + toSel.value;
1354:   }
1355:   body.querySelectorAll('#un-group button').forEach(b=>{
1356:     b.onclick = ()=>{
1357:       body.querySelectorAll('#un-group button').forEach(x=>x.classList.remove('active'));
1358:       b.classList.add('active');
1359:       group = b.dataset.g;
1360:       populate();
1361:     };
1362:   });
1363:   [valInput, fromSel, toSel].forEach(el=>el.addEventListener('input', compute));
1364:   populate();
1365: }
