1431:             <button id="mu-play" style="background:var(--accent);border:none;border-radius:50%;width:44px;height:44px;display:flex;align-items:center;justify-content:center;color:#08110F;cursor:pointer;"><i data-lucide="play"></i></button>
1432:             <button id="mu-next" style="background:none;border:none;color:var(--text-1);cursor:pointer;"><i data-lucide="skip-forward"></i></button>
1433:           </div>
1434:         </div>
1435:         <div id="mu-list" style="flex:1;overflow-y:auto;"></div>
1436:       </div>
1437:     </div>
1438:   `;
1439:   lucide.createIcons();
1440:   const audio = new Audio();
1441:   let idx = 0;
1442:   const titleEl = body.querySelector('#mu-title');
1443:   const artistEl = body.querySelector('#mu-artist');
1444:   const playBtn = body.querySelector('#mu-play');
1445:   const seek = body.querySelector('#mu-seek');
1446:   const curEl = body.querySelector('#mu-cur');
1447:   const durEl = body.querySelector('#mu-dur');
1448:   const listEl = body.querySelector('#mu-list');
1449: 
1450:   function fmt(s){ if(!isFinite(s)) return '0:00'; const m=Math.floor(s/60), sec=Math.floor(s%60); return m+':'+String(sec).padStart(2,'0'); }
1451:   function drawList(){
1452:     listEl.innerHTML = MUSIC_TRACKS.map((t,i)=>`
1453:       <div class="note-row ${i===idx?'active':''}" data-i="${i}" style="display:flex;align-items:center;gap:10px;">
