1474:   });
1475:   audio.addEventListener('play', ()=>{ playBtn.innerHTML = '<i data-lucide="pause"></i>'; lucide.createIcons(); });
1476:   audio.addEventListener('pause', ()=>{ playBtn.innerHTML = '<i data-lucide="play"></i>'; lucide.createIcons(); });
1477:   audio.addEventListener('ended', ()=>{ idx = (idx+1)%MUSIC_TRACKS.length; loadTrack(true); });
1478: 
1479:   playBtn.onclick = ()=>{ audio.paused ? audio.play().catch(()=>{}) : audio.pause(); };
1480:   body.querySelector('#mu-prev').onclick = ()=>{ idx = (idx-1+MUSIC_TRACKS.length)%MUSIC_TRACKS.length; loadTrack(true); };
1481:   body.querySelector('#mu-next').onclick = ()=>{ idx = (idx+1)%MUSIC_TRACKS.length; loadTrack(true); };
1482:   seek.addEventListener('input', ()=>{ if(audio.duration) audio.currentTime = (seek.value/100)*audio.duration; });
1483: 
1484:   loadTrack(false);
1485: }
