91: // ─── Helpers ────────────────────────────────────────────────────
92: function readBody(req) {
93:   return new Promise((resolve, reject) => {
94:     const chunks = [];
95:     req.on('data', c => chunks.push(c));
96:     req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
97:     req.on('error', reject);
98:   });
99: }
100: 
101: function json(res, data, status = 200) {
102:   const body = JSON.stringify(data);
103:   res.writeHead(status, {
104:     'Content-Type': 'application/json',
105:     'Access-Control-Allow-Origin': '*',
106:     'Content-Length': Buffer.byteLength(body)
107:   });
108:   res.end(body);
109: }
110: 
111: function err(res, message, status = 500) {
112:   json(res, { error: message }, status);
113: }
