115: function serveFile(res, filePath) {
116:   try {
117:     const stat = fs.statSync(filePath);
118:     if (stat.isDirectory()) {
119:       const idx = path.join(filePath, 'index.html');
120:       if (fs.existsSync(idx)) return serveFile(res, idx);
121:       return err(res, 'Directory listing not supported', 403);
122:     }
123:     const ext = path.extname(filePath).toLowerCase();
124:     const mime = MIME[ext] || 'application/octet-stream';
125:     const data = fs.readFileSync(filePath);
126:     res.writeHead(200, {
127:       'Content-Type': mime,
128:       'Content-Length': data.length,
129:       'Cache-Control': 'public, max-age=3600'
130:     });
131:     res.end(data);
132:   } catch {
133:     err(res, 'File not found', 404);
134:   }
135: }
