245: // ─── API Router ────────────────────────────────────────────────
246: function handleAPI(req, res, urlPath) {
247:   const method = req.method.toUpperCase();
248: 
249:   // CORS preflight
250:   if (method === 'OPTIONS') {
251:     res.writeHead(204, {
252:       'Access-Control-Allow-Origin': '*',
253:       'Access-Control-Allow-Methods': 'GET, POST, DELETE, PUT, OPTIONS',
254:       'Access-Control-Allow-Headers': 'Content-Type',
255:     });
256:     return res.end();
257:   }
258: 
259:   // ── GET /api/system/info ──────────────────────────────────
260:   if (urlPath === '/api/system/info' && method === 'GET') {
261:     const uptime = os.uptime();
262:     const mem = os.totalmem();
263:     const freemem = os.freemem();
264:     let config = { system: { version: '2.0.0', codename: 'Horizon Bare-Metal' } };
265:     try {
266:       config = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8'));
267:     } catch (_) {}
268: 
269:     return json(res, {
270:       os: 'Endroid OS (Standalone)',
271:       version: config.system?.version || '2.0.0',
272:       codename: config.system?.codename || 'Horizon Bare-Metal',
273:       kernel: `Linux ${os.release()}`,
274:       arch: os.arch(),
275:       platform: os.platform(),
276:       uptime: Math.floor(uptime),
277:       hostname: os.hostname(),
278:       memory: { total: Math.floor(mem / 1024), free: Math.floor(freemem / 1024) },
279:       cpus: os.cpus().length,
280:       load: os.loadavg()
281:     });
282:   }
283: 
284:   // ── GET /api/system/hardware ─────────────────────────────
285:   if (urlPath === '/api/system/hardware' && method === 'GET') {
286:     const cpus = os.cpus();
287:     const cpuModel = cpus.length > 0 ? cpus[0].model : 'x86_64 Processor';
288:     const totalMemGb = (os.totalmem() / (1024 * 1024 * 1024)).toFixed(2);
289:     const freeMemGb = (os.freemem() / (1024 * 1024 * 1024)).toFixed(2);
290:     const usedMemGb = ((os.totalmem() - os.freemem()) / (1024 * 1024 * 1024)).toFixed(2);
291: 
292:     let battery = { present: false, percent: 100, charging: true };
293:     try {
294:       if (fs.existsSync('/sys/class/power_supply/BAT0/capacity')) {
295:         battery.present = true;
296:         battery.percent = parseInt(fs.readFileSync('/sys/class/power_supply/BAT0/capacity', 'utf8').trim()) || 100;
297:         const status = fs.readFileSync('/sys/class/power_supply/BAT0/status', 'utf8').trim();
298:         battery.charging = status === 'Charging' || status === 'Full';
299:       }
300:     } catch (_) {}
301: 
302:     return json(res, {
303:       cpu: {
304:         model: cpuModel,
305:         cores: cpus.length,
306:         speedMhz: cpus.length > 0 ? cpus[0].speed : 2400
307:       },
308:       memory: {
309:         totalGb: totalMemGb,
310:         usedGb: usedMemGb,
311:         freeGb: freeMemGb,
312:         percent: Math.round(((os.totalmem() - os.freemem()) / os.totalmem()) * 100)
313:       },
314:       battery,
315:       disks: scanPhysicalDisks(),
316:       uefi: fs.existsSync('/sys/firmware/efi'),
317:       isBareMetal: os.platform() === 'linux'
318:     });
319:   }
320: 
321:   // ── POST /api/system/shutdown ────────────────────────────
322:   if (urlPath === '/api/system/shutdown' && method === 'POST') {
323:     console.log('[SYSTEM] Executing physical hardware shutdown...');
324:     try {
325:       if (os.platform() === 'linux') {
326:         execSync('sync && (busybox poweroff -f || poweroff -f || shutdown -h now)', { timeout: 3000 });
327:       }
328:     } catch (_) {}
329:     return json(res, { success: true, message: 'System powering off...' });
330:   }
331: 
332:   // ── POST /api/system/reboot ──────────────────────────────
333:   if (urlPath === '/api/system/reboot' && method === 'POST') {
334:     console.log('[SYSTEM] Executing physical hardware reboot...');
335:     try {
336:       if (os.platform() === 'linux') {
337:         execSync('sync && (busybox reboot -f || reboot -f || shutdown -r now)', { timeout: 3000 });
338:       }
339:     } catch (_) {}
340:     return json(res, { success: true, message: 'System restarting...' });
341:   }
342: 
343:   // ── GET /api/installer/disks ─────────────────────────────
344:   if (urlPath === '/api/installer/disks' && method === 'GET') {
345:     const disks = scanPhysicalDisks();
346:     const isUefi = fs.existsSync('/sys/firmware/efi');
347:     return json(res, {
348:       disks,
349:       firmware: isUefi ? 'UEFI' : 'Legacy BIOS',
350:       recommendedBoot: isUefi ? 'uefi' : 'bios'
351:     });
352:   }
353: 
354:   // ── POST /api/installer/install ──────────────────────────
355:   if (urlPath === '/api/installer/install' && method === 'POST') {
356:     return readBody(req).then(body => {
357:       try {
358:         const payload = JSON.parse(body || '{}');
359:         const targetDisk = payload.targetDisk;
360:         const bootType = payload.bootType || 'uefi';
361:         const hostname = payload.hostname || 'endroid-pc';
362:         const username = payload.username || 'tc';
363: 
364:         if (!targetDisk) {
365:           return err(res, 'No target storage disk specified', 400);
366:         }
367: 
368:         console.log(`[INSTALLER] Starting bare-metal deployment to ${targetDisk} (${bootType})...`);
369: 
370:         const isLinux = os.platform() === 'linux';
371:         if (isLinux && fs.existsSync(targetDisk)) {
372:           try {
373:             if (bootType === 'uefi') {
374:               execSync(`parted -s ${targetDisk} mklabel gpt`, { stdio: 'inherit' });
375:               execSync(`parted -s ${targetDisk} mkpart ESP fat32 1MiB 513MiB`, { stdio: 'inherit' });
376:               execSync(`parted -s ${targetDisk} set 1 esp on`, { stdio: 'inherit' });
377:               execSync(`parted -s ${targetDisk} mkpart primary ext4 513MiB 100%`, { stdio: 'inherit' });
378:               execSync('sync && udevadm settle 2>/dev/null || sleep 2');
379: 
380:               const p1 = targetDisk.includes('nvme') ? `${targetDisk}p1` : `${targetDisk}1`;
381:               const p2 = targetDisk.includes('nvme') ? `${targetDisk}p2` : `${targetDisk}2`;
382: 
383:               execSync(`mkfs.vfat -F32 ${p1} 2>/dev/null || mkfs.fat -F32 ${p1}`, { stdio: 'inherit' });
384:               execSync(`mkfs.ext4 -F -L ENDROID_DATA ${p2}`, { stdio: 'inherit' });
385: 
386:               execSync('mkdir -p /mnt/target_root /mnt/target_esp');
387:               execSync(`mount ${p2} /mnt/target_root`);
388:               execSync(`mkdir -p /mnt/target_root/boot/efi`);
389:               execSync(`mount ${p1} /mnt/target_esp`);
390: 
391:               execSync('cp -a /opt/endroid /mnt/target_root/opt/ 2>/dev/null || true');
392:               execSync('cp -a /home/tc /mnt/target_root/home/ 2>/dev/null || true');
393: 
394:               execSync('mkdir -p /mnt/target_esp/EFI/BOOT');
395:               execSync('cp /opt/boot/BOOTX64.EFI /mnt/target_esp/EFI/BOOT/ 2>/dev/null || true');
396:               execSync('cp /opt/boot/vmlinuz /mnt/target_esp/EFI/BOOT/ 2>/dev/null || true');
397:               execSync('cp /opt/boot/initrd.gz /mnt/target_esp/EFI/BOOT/ 2>/dev/null || true');
398: 
399:               execSync('umount /mnt/target_esp 2>/dev/null || true');
400:               execSync('umount /mnt/target_root 2>/dev/null || true');
401:             } else {
402:               execSync(`parted -s ${targetDisk} mklabel msdos`, { stdio: 'inherit' });
403:               execSync(`parted -s ${targetDisk} mkpart primary ext4 1MiB 100%`, { stdio: 'inherit' });
404:               execSync(`parted -s ${targetDisk} set 1 boot on`, { stdio: 'inherit' });
405:               const p1 = targetDisk.includes('nvme') ? `${targetDisk}p1` : `${targetDisk}1`;
406:               execSync(`mkfs.ext4 -F -L ENDROID_DATA ${p1}`, { stdio: 'inherit' });
407:             }
408:           } catch (cmdErr) {
409:             console.warn('[INSTALLER] Non-fatal command error during installation:', cmdErr);
410:           }
411:         }
412: 
413:         return json(res, {
414:           success: true,
415:           targetDisk,
416:           bootType,
417:           message: `Endroid OS successfully installed to ${targetDisk}! You can now remove the installation USB and reboot your PC.`
418:         });
419:       } catch (e) {
420:         return err(res, `Installation error: ${e.message}`, 500);
421:       }
422:     });
423:   }
424: 
425:   // ── GET /api/network/interfaces ──────────────────────────
426:   if (urlPath === '/api/network/interfaces' && method === 'GET') {
427:     const ifaces = os.networkInterfaces();
428:     const result = [];
429:     for (const [name, addrs] of Object.entries(ifaces)) {
430:       const ipv4 = addrs.find(a => a.family === 'IPv4' && !a.internal);
431:       result.push({
432:         name,
433:         type: name.startsWith('wl') || name.startsWith('wifi') ? 'Wi-Fi' : (name.startsWith('eth') || name.startsWith('en') ? 'Ethernet' : 'Other'),
434:         ip: ipv4 ? ipv4.address : 'Disconnected / DHCP',
435:         netmask: ipv4 ? ipv4.netmask : null,
436:         mac: addrs[0]?.mac || 'Unknown',
437:         connected: Boolean(ipv4)
