442: 
443:   // ── GET /api/system/config ───────────────────────────────
444:   if (urlPath === '/api/system/config' && method === 'GET') {
445:     try {
446:       return json(res, JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8')));
447:     } catch (_) {
448:       return json(res, { theme: { mode: 'dark' } });
449:     }
450:   }
451: 
452:   // ── POST /api/system/config ──────────────────────────────
453:   if (urlPath === '/api/system/config' && method === 'POST') {
454:     return readBody(req).then(body => {
455:       try {
456:         const data = JSON.parse(body);
457:         let current = {};
458:         try {
459:           current = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8'));
460:         } catch (_) {}
461:         const merged = Object.assign({}, current, data);
462:         fs.writeFileSync(CONFIG_FILE, JSON.stringify(merged, null, 2));
463:         json(res, { success: true, config: merged });
464:       } catch (e) {
465:         err(res, e.message, 400);
466:       }
467:     });
468:   }
469: 
470:   // ── GET /api/apps ────────────────────────────────────────
471:   if (urlPath === '/api/apps' && method === 'GET') {
472:     try {
473:       return json(res, JSON.parse(fs.readFileSync(APPS_FILE, 'utf8')));
474:     } catch (_) {
475:       return json(res, { systemApps: [], installedApps: [] });
476:     }
477:   }
478: 
479:   // ── GET /api/fs?path=... ─────────────────────────────────
480:   if (urlPath.startsWith('/api/fs') && method === 'GET') {
481:     const qp = new URLSearchParams(urlPath.split('?')[1] || '');
482:     const reqPath = qp.get('path') || '/';
483:     const absPath = path.join(VFS_ROOT, reqPath.replace(/^\/+/, ''));
484: 
485:     if (!absPath.startsWith(VFS_ROOT)) return err(res, 'Forbidden', 403);
486: 
487:     try {
488:       const stat = fs.statSync(absPath);
489:       if (stat.isDirectory()) {
490:         const entries = fs.readdirSync(absPath).map(name => {
491:           const fp = path.join(absPath, name);
492:           try {
493:             const s = fs.statSync(fp);
494:             return {
495:               name,
496:               type: s.isDirectory() ? 'directory' : 'file',
497:               isDirectory: s.isDirectory(),
498:               size: s.size,
499:               ext: path.extname(name).toLowerCase(),
500:               mtime: s.mtime.toISOString(),
501:               path: path.join(reqPath, name).replace(/\\/g, '/')
502:             };
503:           } catch { return null; }
504:         }).filter(Boolean);
505:         return json(res, { path: reqPath, entries });
506:       } else {
507:         const content = fs.readFileSync(absPath, 'utf8');
508:         return json(res, { path: reqPath, content, size: stat.size });
509:       }
510:     } catch (e) {
511:       return err(res, e.message, 404);
512:     }
513:   }
514: 
515:   // ── POST /api/fs?path=... ────────────────────────────────
516:   if (urlPath.startsWith('/api/fs') && method === 'POST') {
517:     const qp = new URLSearchParams(urlPath.split('?')[1] || '');
518:     const reqPath = qp.get('path') || '/';
519:     const absPath = path.join(VFS_ROOT, reqPath.replace(/^\/+/, ''));
520:     if (!absPath.startsWith(VFS_ROOT)) return err(res, 'Forbidden', 403);
521: 
522:     return readBody(req).then(body => {
523:       try {
524:         const { content, type } = JSON.parse(body || '{}');
525:         if (type === 'directory') {
526:           fs.mkdirSync(absPath, { recursive: true });
527:         } else {
528:           fs.mkdirSync(path.dirname(absPath), { recursive: true });
529:           fs.writeFileSync(absPath, content || '');
530:         }
531:         json(res, { success: true, path: reqPath });
532:       } catch (e) {
533:         err(res, e.message, 400);
534:       }
535:     });
536:   }
537: 
538:   // ── DELETE /api/fs?path=... ──────────────────────────────
539:   if (urlPath.startsWith('/api/fs') && method === 'DELETE') {
540:     const qp = new URLSearchParams(urlPath.split('?')[1] || '');
541:     const reqPath = qp.get('path') || '/';
542:     const absPath = path.join(VFS_ROOT, reqPath.replace(/^\/+/, ''));
543:     if (!absPath.startsWith(VFS_ROOT)) return err(res, 'Forbidden', 403);
544: 
545:     try {
